from itertools import product

def find_valid_combination():
    # Define prices and target values
    price_a = 0.50
    price_b = 3.00
    price_c = 10.50
    target_total_cost = 50.00
    target_total_items = 100

    # Iterate over possible numbers of each item type
    for num_a in range(1, int(target_total_items / (price_a + price_b + price_c))):
        for num_b in range(1, int((target_total_items - num_a) / (price_b + price_c))):
            num_c = target_total_items - num_a - num_b
            if num_c > 0:
                # Calculate total cost
                total_cost = (num_a * price_a) + (num_b * price_b) + (num_c * price_c)
                if abs(total_cost - target_total_cost) < 1e-6:
                    return {'num_a': num_a, 'num_b': num_b, 'num_c': num_c}
    return None

result = find_valid_combination()
if result:
    print(result)
else:
    print('No valid combination found.')
